/// <summary>
/// PaffH 28.08.25
/// </summary>
[ExtensionOf(FormStr(DirPartyQuickCreateForm))]
final class NDXDirPartyQuickCreateForm_frm_Extension
{
    public NDXBVSearchContract nDXBVSearchContract;

}

Method.Source:
/// <summary>
/// PaffH 28.08.25
/// </summary>        
public void init()
{
    next init();

    DirPartyFormHandler_Entity formHandler = this.parmPartyForm();
    //DirPartyType partyType = formHandler.parmPartyType();

    // get NDXBVSearchContract from caller
    Args elementArgs = this.args();

    if (elementArgs
        && elementArgs.caller())
    {
        FormRun callerForm;
        if (elementArgs.caller() is FormRun)
        {
            callerForm = elementArgs.caller() as FormRun;
        }
        if (callerForm)
        {
            Args callerArgs = callerForm.args();
            if (callerArgs
                && callerArgs.parmObject())
            {
                if (callerArgs.parmObject() is NDXBVSearchContract)
                {
                    nDXBVSearchContract = callerArgs.parmObject() as NDXBVSearchContract;
                }
            }
        }
    }
}

/// <summary>
/// PaffH 30.08.25
/// last modified: PaffH 29.11.25
/// </summary>
public void refreshUI()
{
    next refreshUI();

    DirPartyFormHandler_Entity formHandler = this.parmPartyForm();
    DirPartyType partyType = formHandler.parmPartyType();
    if (partyType == DirPartyType::Person)
    {
        if (nDXBVSearchContract)
        {
            if (nDXBVSearchContract.parmContactPersonEmail())
            {
                LogisticsElectronicAddressEmail.Locator = nDXBVSearchContract.parmContactPersonEmail();
            }
            DirNameAffix dirNameAffix;
            if (nDXBVSearchContract.parmContactPersonTitle())
            {
                select firstonly * from dirNameAffix where dirNameAffix.Affix == nDXBVSearchContract.parmContactPersonTitle();
            }
            if (!dirNameAffix)
            {
                select firstonly * from dirNameAffix where dirNameAffix.Affix == 'Herr';
            }
            dirPartyTable_DirPerson.PersonalTitle = dirNameAffix.RecId;

            if (nDXBVSearchContract.parmContactPersonFirstName() || nDXBVSearchContract.parmContactPersonLastName())
            {
                if (nDXBVSearchContract.parmContactPersonFirstName())
                {
                    DirPersonName.FirstName = nDXBVSearchContract.parmContactPersonFirstName();
                }
                if (nDXBVSearchContract.parmContactPersonLastName())
                {
                    DirPersonName.LastName = nDXBVSearchContract.parmContactPersonLastName();
                }
                DirPersonName_ds.modified();
            }
        }
    }
}
